,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_api.id(5792175864974744)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'BODY'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
wwv_flow_api.create_report_region(
 p_id=>wwv_flow_api.id(25822216949623212)
,p_name=>'<span style="color:#00096B;font-weight:bold">Process Status:</span'
,p_template=>wwv_flow_api.id(5792175864974744)
,p_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'BODY'
,p_item_display_point=>'BELOW'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-----------------------------------------------------',
'--  To show P10_STATUS below percent graph:',
'--     Apperance',
'--     Item Display Position: Below Content',
'-----------------------------------------------------',
'declare',
'   v_percent    number := 0;',
'   v_file       utl_file.file_type;',
'   v_line       varchar2(200);',
'   v_fname      varchar2(100);',
'   v_uniqid     varchar2(30);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   if :P10_CLR_STATUS = ''Y'' then',
'      null;',
'   else',
'      execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'      v_uniqid := :P10_UNIQID;',
'      v_fname := ''CAJR40020_gen_apx'' || v_uniqid || ''.pct'';',
'      utl_file.fgetattr (''DIR_TMP'', v_fname, v_fexists, v_flength, v_fblksiz);',
'      if v_fexists then',
'         v_file := utl_file.fopen (''DIR_TMP'', v_fname, ''R'');',
'         utl_file.get_line (v_file, v_percent);',
'         utl_file.fclose (v_file);',
'      end if;',
'   end if;',
'   return ''select ''|| v_percent || '' as pct1, '' || v_percent || '' as pct2 from dual'';',
'end;'))
,p_ajax_enabled=>'Y'
,p_query_row_template=>wwv_flow_api.id(5815222959974737)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>'-'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
wwv_flow_api.create_report_columns(
 p_id=>wwv_flow_api.id(5902611077554117)
,p_query_column_id=>1
,p_column_alias=>'PCT1'
,p_column_display_sequence=>1
,p_column_heading=>'<span style="font-size:17px;font-weight:bold">%Reports Complete</span'
,p_column_format=>'PCT_GRAPH:#C7C7CC:#6B000F:'
,p_display_as=>'WITHOUT_MODIFICATION'
,p_report_column_width=>300
,p_derived_column=>'N'
