wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5904277909554114)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P10_PRC_GetReport_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'---------------------------------------------',
'-- Invoke external program',
'---------------------------------------------',
'',
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2 (200);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'   v_uniqid     varchar2(30);',
'   v_appusr     varchar2(15);',
'   v_fname      varchar2(30);',
'   v_jobargs    varchar2(100);',
'',
'begin',
'   dbms_scheduler.drop_credential (''recuser_credential'', true);',
'   dbms_scheduler.create_credential (',
'      credential_name => ''recuser_credential'',',
'      username        => ''recuser'',',
'      password        => ''desAdmin1''',
'   );',
'   dbms_scheduler.create_job (',
'      job_name             => ''CAJR40020_gen_job'',',
'      job_type             => ''executable'',',
'      number_of_arguments  => 1,',
'      job_action           => ''/home/sysoper/recuser/CAJR40020_gen.sh'',',
'      auto_drop            => true,',
'      credential_name      => ''recuser_credential''',
'   );',
'',
'   v_uniqid := dbms_session.unique_session_id;',
'   v_appusr := :APP_USER;',
'   if :P10_GLOBAL_REPORT = ''Y'' then',
'      v_jobargs := ''9999'' || '':'' || :P10_START_DATE || '':'' || :P10_END_DATE || '':--sid='' || v_uniqid || '':--usr='' || v_appusr;',
'   else',
'      v_jobargs := :P10_PRCODE || '':'' || :P10_START_DATE || '':'' || :P10_END_DATE || '':--sid='' || v_uniqid || '':--usr='' || v_appusr;',
'      if :P10_EMAIL = ''Y'' then',
'         v_jobargs := v_jobargs || '':--eml'';',
'      end if;',
'   end if;',
'   dbms_scheduler.set_job_argument_value (''CAJR40020_gen_job'', 1, v_jobargs);',
'   dbms_scheduler.enable (''CAJR40020_gen_job'');   ',
'   -- Allow time for external program to reset Apex status --',
'   dbms_lock.sleep (1);',
'   ',
'   :P10_CLR_STATUS := null;',
'   :P10_STATUS := ''Generating CAJR40020 report(s) ...'';',
'   :P10_UNIQID := v_uniqid;',
'--   exception',
'--      when others then',
'--         raise_application_error (-20999, ''PROCESS ALREADY RUNNING - TRY LATER'');',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5897983676554122)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5904672679554114)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P10_PRC_ClearStatus'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-----------------------------------------------------',
'--  Server-side Condition',
'--  Type: PL/SQL Expression',
'--     :REQUEST in (''P10_PRCODE'', ''P10_GLOBAL_REPORT'')',
'-----------------------------------------------------',
'declare',
'   v_file       utl_file.file_type;',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'   utl_file.fgetattr (''DIR_TMP'', ''CAJR40020_gen.pid'', v_fexists, v_flength, v_fblksiz);',
'   if v_fexists then',
'      null;',
'   else',
'      :P10_CLR_STATUS := ''Y'';',
'      :P10_STATUS := null;',
'      :P10_START_DATE := null;',
'      :P10_END_DATE := null;',
'      :P10_EMAIL := ''N'';',
'      :P10_ENDIC := null;',
'      :P10_WARN := null;',
'      if :P10_GLOBAL_REPORT = ''Y'' then',
'         :P10_PRCODE := 0;',
'      end if;',
'   end if;',
'end;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST in (''P10_PRCODE'', ''P10_GLOBAL_REPORT'')'
,p_process_when_type=>'PLSQL_EXPRESSION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5905093449554114)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P10_PRC_UpdateStatus_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2(200);',
'   v_fname      varchar2(100);',
'   v_uniqid     varchar2(30);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'   ',
'begin',
'   if :P10_CLR_STATUS = ''Y'' then',
'      null;',
'   else',
'      execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'      v_uniqid := :P10_UNIQID;',
'      v_fname := ''CAJR40020_gen_apx'' || v_uniqid || ''.log'';',
'      utl_file.fgetattr (''DIR_TMP'', v_fname, v_fexists, v_flength, v_fblksiz);',
'      if v_fexists then',
'         v_file := utl_file.fopen (''DIR_TMP'', v_fname, ''R'');',
'         :P10_STATUS := null;',
'         loop',
'            utl_file.get_line (v_file, v_line);',
'            :P10_STATUS := :P10_STATUS || v_line || chr(13);',
'            if v_line like ''%ERROR:%'' or v_line like ''%WARNING:%'' then',
'               :P10_WARN := ''Y'';',
'            end if;',
'         end loop;',
'      end if;',
'   end if;',
'   exception',
'      when no_data_found then',
'         utl_file.fclose (v_file);',
'         if v_line = ''Process completed.'' then',
'            if :P10_WARN = ''Y'' then',
'               :P10_ENDIC := ''#APP_IMAGES#icons8-warning-48.png'';',
'            else',
'               :P10_ENDIC := ''#APP_IMAGES#icons8-ok-48.png'';',
'            end if;',
'         end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5898333375554122)
);
end;
/
