,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P15_PRC_GetReport_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'---------------------------------------------',
'-- Invoke external program',
'---------------------------------------------',
'',
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2 (200);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'   v_uniqid     varchar2(30);',
'   v_appusr     varchar2(15);',
'   v_fname      varchar2(30);',
'   v_jobargs    varchar2(100);',
'',
'begin',
'   dbms_scheduler.drop_credential (''recuser_credential'', true);',
'   dbms_scheduler.create_credential (',
'      credential_name => ''recuser_credential'',',
'      username        => ''recuser'',',
'      password        => ''desAdmin1''',
'   );',
'   dbms_scheduler.create_job (',
'      job_name             => ''PROR30090_gen_job'',',
'      job_type             => ''executable'',',
'      number_of_arguments  => 1,',
'      job_action           => ''/home/sysoper/recuser/PROR30090_gen.sh'',',
'      auto_drop            => true,',
'      credential_name      => ''recuser_credential''',
'   );',
'',
'   v_uniqid := dbms_session.unique_session_id;',
'   v_appusr := :APP_USER;',
'   v_jobargs := :P15_PRCODE || '':'' || :P15_PAY_DATE || '':--sid='' || v_uniqid || '':--usr='' || v_appusr;',
'   dbms_scheduler.set_job_argument_value (''PROR30090_gen_job'', 1, v_jobargs);',
'   dbms_scheduler.enable (''PROR30090_gen_job'');   ',
'   -- Allow time for external program to reset Apex status --',
'   dbms_lock.sleep (1);',
'   ',
'   :P15_CLR_STATUS := null;',
'   :P15_UNIQID := v_uniqid;',
'   :P15_WARN := null;',
'   :P15_ERROR := null;',
'   :P15_ENDIC := null;',
'   :P15_STATUS := ''Generating PROR30090 report ...'';',
'   exception',
'      when others then',
'         raise_application_error (-20999, ''PROCESS ALREADY RUNNING - TRY LATER'');',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(6179620953092276)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(6185932534092254)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P15_PRC_ClearStatus'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-----------------------------------------------------',
'--  Server-side Condition',
'--  Type: PL/SQL Expression',
'--     :REQUEST in (''P15_PRCODE'')',
'-----------------------------------------------------',
'declare',
'   v_file       utl_file.file_type;',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'   utl_file.fgetattr (''DIR_TMP'', ''PROR30090_gen.pid'', v_fexists, v_flength, v_fblksiz);',
'   if v_fexists then',
'      null;',
'   else',
'      :P15_CLR_STATUS := ''Y'';',
'      :P15_STATUS := null;',
'      :P15_PAY_DATE := null;',
'      :P15_ENDIC := null;',
'      :P15_WARN := null;',
'      :P15_ERROR := null;',
'   end if;',
'end;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST in (''P15_PRCODE'')'
,p_process_when_type=>'PLSQL_EXPRESSION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(6186313877092254)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P15_PRC_UpdateStatus_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2(200);',
'   v_fname      varchar2(100);',
'   v_uniqid     varchar2(30);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   if :P15_CLR_STATUS = ''Y'' then',
'      null;',
'   else',
'      execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'      v_uniqid := :P15_UNIQID;',
'      v_fname := ''PROR30090_gen_apx'' || v_uniqid || ''.log'';',
'      utl_file.fgetattr (''DIR_TMP'', v_fname, v_fexists, v_flength, v_fblksiz);',
'      if v_fexists then',
'         v_file := utl_file.fopen (''DIR_TMP'', v_fname, ''R'');',
'         :P15_STATUS := null;',
'         loop',
'            utl_file.get_line (v_file, v_line);',
'            :P15_STATUS := :P15_STATUS || v_line || chr(13);',
'            if v_line like ''%ERROR:%'' then',
'               :P15_ERROR := ''Y'';',
'            elsif v_line like ''%WARNING:%'' then',
'               :P15_WARN := ''Y'';',
'            end if;',
'         end loop;',
'      end if;',
'   end if;',
'   exception',
'      when no_data_found then',
'         utl_file.fclose (v_file);',
'         if v_line = ''Process completed.'' then',
'            if :P15_ERROR = ''Y'' then',
'               :P15_ENDIC := ''#APP_IMAGES#icons8-cancel-48.png'';',
'            elsif :P15_WARN = ''Y'' then',
'               :P15_ENDIC := ''#APP_IMAGES#icons8-warning-48.png'';',
'            else',
'               :P15_ENDIC := ''#APP_IMAGES#icons8-ok-48.png'';',
'            end if;',
'         end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(6179245717092277)
);
end;
