wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5928994269178233)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P30_PRC_SendEmail_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'---------------------------------------------',
'-- Invoke external program',
'---------------------------------------------',
'',
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2 (200);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'   v_uniqid     varchar2(30);',
'   v_appusr     varchar2(15);',
'   v_fname      varchar2(30);',
'   v_jobargs    varchar2(100);',
'',
'begin',
'   dbms_scheduler.drop_credential (''recuser_credential'', true);',
'   dbms_scheduler.create_credential (',
'      credential_name => ''recuser_credential'',',
'      username        => ''recuser'',',
'      password        => ''desAdmin1''',
'   );',
'   dbms_scheduler.create_job (',
'      job_name             => ''ACHemnotif_job'',',
'      job_type             => ''executable'',',
'      number_of_arguments  => 1,',
'      job_action           => ''/home/sysoper/recuser/ACHemnotif.sh'',',
'      auto_drop            => true,',
'      credential_name      => ''recuser_credential''',
'   );',
'',
'   if :P30_EMAIL = ''Y'' then',
'      v_uniqid := dbms_session.unique_session_id;',
'      v_appusr := :APP_USER;',
'      if :P30_PRCODE = ''0'' then',
'         v_jobargs := '':--sid='' || v_uniqid || '':--usr='' || v_appusr;',
'      else',
'         v_jobargs := :P30_PRCODE || '':--sid='' || v_uniqid || '':--usr='' || v_appusr;',
'      end if;',
'      dbms_scheduler.set_job_argument_value (''ACHemnotif_job'', 1, v_jobargs);',
'      dbms_scheduler.enable (''ACHemnotif_job'');',
'      -- Allow time for external program to reset Apex status --',
'      dbms_lock.sleep (1);',
'      :P30_STATUS := ''Sending PROR30090 report to producers ...'';',
'   else',
'      dbms_scheduler.drop_job (job_name => ''ACHemnotif_job'');',
'      :P30_STATUS := null;',
'      dbms_lock.sleep (1);',
'   end if;',
'   :P30_CLR_STATUS := null;',
'   :P30_ENDIC := null;',
'   :P30_WARN := null;',
'   :P30_UNIQID := v_uniqid;',
'   exception',
'      when others then',
'         raise_application_error (-20999, ''PROCESS ALREADY RUNNING - TRY LATER'');',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5924669915178235)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5929335456178233)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P30_PRC_ClearStatus'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-----------------------------------------------------',
'--  Server-side Condition',
'--  Type: PL/SQL Expression',
'--     :REQUEST in (''P30_PRCODE'')',
'-----------------------------------------------------',
'declare',
'   v_file       utl_file.file_type;',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'   utl_file.fgetattr (''DIR_TMP'', ''ACHemnotif.pid'', v_fexists, v_flength, v_fblksiz);',
'   if v_fexists then',
'      null;',
'   else',
'      :P30_CLR_STATUS := ''Y'';',
'      :P30_STATUS := null;',
'      :P30_ENDIC := null;',
'      :P30_WARN := null;',
'      :P30_EMAIL := null;',
'   end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST in (''P30_PRCODE'')'
,p_process_when_type=>'PLSQL_EXPRESSION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5929708465178233)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P30_PRC_UpdateStatus_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2(200);',
'   v_fname      varchar2(100);',
'   v_uniqid     varchar2(30);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'   ',
'begin',
'   if :P30_CLR_STATUS = ''Y'' then',
'      null;',
'   else',
'      execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'      v_uniqid := :P30_UNIQID;',
'      v_fname := ''ACHemnotif_apx'' || v_uniqid || ''.log'';',
'      utl_file.fgetattr (''DIR_TMP'', v_fname, v_fexists, v_flength, v_fblksiz);',
'      if v_fexists then',
'         v_file := utl_file.fopen (''DIR_TMP'', v_fname, ''R'');',
'         :P30_STATUS := null;',
'         loop',
'            utl_file.get_line (v_file, v_line);',
'            :P30_STATUS := :P30_STATUS || v_line || chr(13);',
'            if v_line like ''%ERROR:%'' or v_line like ''%WARNING:%'' then',
'               :P30_WARN := ''Y'';',
'            end if;',
'         end loop;',
'      end if;',
'   end if;',
'   exception',
'      when no_data_found then',
'         utl_file.fclose (v_file);',
'         if v_line = ''Process completed.'' then',
'            if :P30_WARN = ''Y'' then',
'               :P30_ENDIC := ''#APP_IMAGES#icons8-warning-48.png'';',
'            else',
'               :P30_ENDIC := ''#APP_IMAGES#icons8-ok-48.png'';',
'            end if;',
'         end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5925054948178235)
);
end;
