wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(6287722398618504)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P50_Rnd_getLastClos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P50_COMPANY_ID is null then',
'   :P50_COMPANY_ID := 1;',
'end if;',
'select * into :P50_LAST_CLOS from (',
'   select cjne_fe_cierre_diario',
'   from cajt_numeracion_egresos',
'   where cjne_fe_cierre_diario between to_date (''01-01-2000'',''DD-MM-YYYY'') and',
'                                       to_date (to_char(SYSDATE,''dd-mm-yyyy''),''DD-MM-YYYY'') and',
'         cjne_cjcm_cd_compania = :P50_COMPANY_ID',
'   order by cjne_fe_cierre_diario desc)',
'where ROWNUM = 1;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5950433948420198)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P50_PRC_Submit_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'---------------------------------------------',
'-- Invoke external program',
'---------------------------------------------',
'',
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2 (200);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'   v_uniqid     varchar2(30);',
'   v_appusr     varchar2(15);',
'   v_fname      varchar2(30);',
'   v_jobargs    varchar2(100);',
'',
'begin',
'   dbms_scheduler.drop_credential (''recuser_credential'', true);',
'   dbms_scheduler.create_credential (',
'      credential_name => ''recuser_credential'',',
'      username        => ''recuser'',',
'      password        => ''desAdmin1''',
'   );',
'   dbms_scheduler.create_job (',
'      job_name             => ''QBchecks_job'',',
'      job_type             => ''executable'',',
'      number_of_arguments  => 1,',
'      job_action           => ''/home/sysoper/recuser/QBchecks.sh'',',
'      auto_drop            => true,',
'      credential_name      => ''recuser_credential''',
'   );',
'',
'   v_uniqid := dbms_session.unique_session_id;',
'   v_appusr := :APP_USER;',
'   v_jobargs := :P50_START_DATE || '':'' || :P50_END_DATE || '':'' || :P50_COMPANY_ID || '':'' ||',
'                   :P50_CKNUM_PT || '':--sid='' || v_uniqid || '':--usr='' || v_appusr;',
'   dbms_scheduler.set_job_argument_value (''QBchecks_job'', 1, v_jobargs);',
'   dbms_scheduler.enable (''QBchecks_job'');',
'   -- Allow time for external program to reset Apex status --',
'   dbms_lock.sleep (1);',
'',
'   :P50_CLR_STATUS := null;',
'   :P50_STATUS := ''Connecting to database ...'';',
'   :P50_ENDIC := null;',
'   :P50_WARN := null;',
'   :P50_ERROR := null;',
'   :P50_UNIQID := v_uniqid;',
'   exception',
'      when others then',
'         raise_application_error (-20999, ''PROCESS ALREADY RUNNING - TRY LATER'');',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5944540328420206)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5951262387420197)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P50_PRC_UpdateStatus_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2(200);',
'   v_fname      varchar2(100);',
'   v_uniqid     varchar2(30);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'begin',
'   if :P50_CLR_STATUS = ''Y'' then',
'      null;',
'   else',
'      execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'      v_uniqid := :P50_UNIQID;',
'      v_fname := ''QBchecks_apx'' || v_uniqid || ''.log'';',
'      utl_file.fgetattr (''DIR_TMP'', v_fname, v_fexists, v_flength, v_fblksiz);',
'      if v_fexists then',
'         v_file := utl_file.fopen (''DIR_TMP'', v_fname, ''R'');',
'         :P50_STATUS := null;',
'         loop',
'            utl_file.get_line (v_file, v_line);',
'            :P50_STATUS := :P50_STATUS || v_line || chr(13);',
'            if v_line like ''%ended with errors%'' then',
'               :P50_ERROR := ''Y'';',
'            end if;',
'         end loop;',
'      end if;',
'   end if;',
'   exception',
'      when no_data_found then',
'         utl_file.fclose (v_file);',
'         if v_line = ''Process completed.'' then',
'            if :P50_ERROR = ''Y'' then',
'               :P50_ENDIC := ''#APP_IMAGES#icons8-cancel-48.png'';',
'            else',
'               :P50_ENDIC := ''#APP_IMAGES#icons8-ok-48.png'';',
'            end if;',
'         end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(5944160912420206)
);
end;
/
