'-----------------------------------------------------',
'--  To show P60_STATUS below percent graph:',
'--     Apperance',
'--     Item Display Position: Below Content',
'-----------------------------------------------------',
'declare',
'   v_percent    number := 0;',
'   v_file       utl_file.file_type;',
