wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(6053967556278979)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P60_PRC_GetReport_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'---------------------------------------------',
'-- Invoke external program',
'---------------------------------------------',
'',
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2 (200);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'   v_uniqid     varchar2(30);',
'   v_appusr     varchar2(15);',
'   v_fname      varchar2(30);',
'   v_jobargs    varchar2(100);',
'',
'begin',
'   dbms_scheduler.drop_credential (''recuser_credential'', true);',
'   dbms_scheduler.create_credential (',
'      credential_name => ''recuser_credential'',',
'      username        => ''recuser'',',
'      password        => ''desAdmin1''',
'   );',
'   dbms_scheduler.create_job (',
'      job_name             => ''Transmittals_job'',',
'      job_type             => ''executable'',',
'      number_of_arguments  => 1,',
'      job_action           => ''/home/sysoper/recuser/Transmittals.sh'',',
'      auto_drop            => true,',
'      credential_name      => ''recuser_credential''',
'   );',
'',
'   v_uniqid := dbms_session.unique_session_id;',
'   v_appusr := :APP_USER;',
'   v_jobargs := :P60_AGCODE || '':'' || :P60_START_DATE || '':'' || :P60_END_DATE || '':--sid='' || v_uniqid || '':--usr='' || v_appusr;',
'   if :P60_EMAIL = ''Y'' then',
'      v_jobargs := v_jobargs || '':--eml'';',
'   end if;',
'   dbms_scheduler.set_job_argument_value (''Transmittals_job'', 1, v_jobargs);',
'   dbms_scheduler.enable (''Transmittals_job'');',
'   -- Allow time for external program to reset Apex status --',
'   dbms_lock.sleep (1);',
'',
'   :P60_CLR_STATUS := null;',
'   :P60_STATUS := ''Generating Transmittal report(s) ...'';',
'   :P60_UNIQID := v_uniqid;',
'   exception',
'      when others then',
'         raise_application_error (-20999, ''PROCESS ALREADY RUNNING - TRY LATER'');',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(6048068531278988)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(6054375978278979)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P60_PRC_ClearStatus'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-----------------------------------------------------',
'--  Server-side Condition',
'--  Type: PL/SQL Expression',
'--     :REQUEST in (''P60_AGCODE'')',
'-----------------------------------------------------',
'declare',
'   v_file       utl_file.file_type;',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'   utl_file.fgetattr (''DIR_TMP'', ''Transmittals.pid'', v_fexists, v_flength, v_fblksiz);',
'   if v_fexists then',
'      null;',
'   else',
'      :P60_CLR_STATUS := ''Y'';',
'      :P60_STATUS := null;',
'      :P60_START_DATE := null;',
'      :P60_END_DATE := null;',
'      :P60_EMAIL := ''N'';',
'      :P60_ENDIC := null;',
'      :P60_WARN := null;',
'   end if;',
'end;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST in (''P60_AGCODE'')'
,p_process_when_type=>'PLSQL_EXPRESSION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(6054796559278979)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P60_PRC_UpdateStatus_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2(200);',
'   v_fname      varchar2(100);',
'   v_uniqid     varchar2(30);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   if :P60_CLR_STATUS = ''Y'' then',
'      null;',
'   else',
'      execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'      v_uniqid := :P60_UNIQID;',
'      v_fname := ''Transmittals_apx'' || v_uniqid || ''.log'';',
'      utl_file.fgetattr (''DIR_TMP'', v_fname, v_fexists, v_flength, v_fblksiz);',
'      if v_fexists then',
'         v_file := utl_file.fopen (''DIR_TMP'', v_fname, ''R'');',
'         :P60_STATUS := null;',
'         loop',
'            utl_file.get_line (v_file, v_line);',
'            :P60_STATUS := :P60_STATUS || v_line || chr(13);',
'            if v_line like ''%ERROR:%'' or v_line like ''%WARNING:%'' then',
'               :P60_WARN := ''Y'';',
'            end if;',
'         end loop;',
'      end if;',
'   end if;',
'   exception',
'      when no_data_found then',
'         utl_file.fclose (v_file);',
'         if v_line = ''Process completed.'' then',
'            if :P60_WARN = ''Y'' then',
'               :P60_ENDIC := ''#APP_IMAGES#icons8-warning-48.png'';',
'            else',
'               :P60_ENDIC := ''#APP_IMAGES#icons8-ok-48.png'';',
'            end if;',
'         end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(6047665139278988)
);
end;
/
